#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26 (v2: multi-row, full sensing -> control chain)
"""One-figure view of an end-to-end cause-effect chain through the FISH task set (extract_fish_tasks.py JSON):
boxes = callbacks (node / entity, C p50, instances), solid arrows = trigger edges inside a task (evidence label, hop latency
p50), dotted arrows = links BETWEEN tasks (sampled read with its measured age, or a state candidate), colour = task.
The chain is a list of (node substring, entity substring, label[, incoming-link topic hint]); task ids are resolved from the
JSON. Rows break at ROW_BREAKS.   python3 chain_figure.py <fish_tasks.json> -o chain.svg [--html chain.html] [--spec spec.json]"""
import argparse, html, json, math

DEFAULT_CHAIN = [  # (node contains, entity contains, label, link-topic hint or None)
    ('/rosbag2_player', 'top/velodyne_packets', 'rosbag player\nthread → top LiDAR packets', None),
    ('top/velodyne_ros_wrapper_node', 'top/velodyne_packets', 'velodyne\nconverter (top)', None),
    ('top/crop_box_filter_self', 'pointcloud_raw_ex', 'crop box\nfilter self', None),
    ('top/crop_box_filter_mirror', 'self_cropped', 'crop box\nfilter mirror', None),
    ('top/distortion_corrector_node', 'mirror_cropped', 'distortion\ncorrector', None),
    ('top/ring_outlier_filter', 'rectified', 'ring outlier\nfilter', None),
    ('concatenate_data', 'top/pointcloud_before_sync', 'concatenate\ndata', None),
    ('lidar_centerpoint', 'concatenated/pointcloud', 'lidar\ncenterpoint (GPU)', None),
    ('obstacle_pointcloud_based_validator', 'centerpoint/objects', 'validator\nobjects input (stores)', None),
    ('obstacle_pointcloud_based_validator', 'pointcloud_map_filtered/pointcloud', 'validator\nsync callback (publishes)', None),
    ('multi_object_tracker', 'centerpoint/validation/objects', 'tracker input\n(stores the detections)', None),
    ('multi_object_tracker', 'detection_by_tracker/objects', 'tracker trigger callback\n(reads + tracks)', None),
    ('multi_object_tracker', 'timer_10000000ns', 'tracker timer 10 ms\n(publishes tracks)', None),
    ('map_based_prediction', 'tracking/objects', 'map based\nprediction', None),
    ('behavior_path_planner', 'timer_100000000ns', 'behavior path planner\ntimer 100 ms', 'object_recognition/objects'),
    ('behavior_velocity_planner', 'path_with_lane_id', 'behavior velocity\nplanner', None),
    ('elastic_band_smoother', 'behavior_planning/path', 'elastic band\nsmoother', None),
    ('path_optimizer', 'path_smoother/path', 'path\noptimizer', None),
    ('motion_velocity_planner', 'path_optimizer/trajectory', 'motion velocity\nplanner', None),
    ('scenario_selector', 'lane_driving/trajectory', 'scenario\nselector', None),
    ('velocity_smoother', 'scenario_selector/trajectory', 'velocity\nsmoother', None),
    ('planning_validator', 'velocity_smoother/trajectory', 'planning\nvalidator', None),
    ('controller_node_exe', 'timer_30000000ns', 'trajectory follower\ncontroller 30 ms', '/planning/trajectory'),
    ('vehicle_cmd_gate', 'trajectory_follower/control_cmd', 'vehicle\ncmd gate', None),
    ('control_validator', 'command/control_cmd', 'control\nvalidator', None),
]
DEFAULT_ROW_BREAKS = [7, 14, 22]
DEFAULT_SIDE = {6: ('+ left LiDAR chain and right LiDAR chain join here', True),
                9: ('trigger: map-filtered pointcloud (obstacle segmentation branch, same task)', False),
                14: ('also reads: kinematic_state, occupancy grid, route, map', False),
                22: ('also reads: kinematic_state, steering status', False)}
END_NOTE = ['chain ends here in the logging simulator:', 'no vehicle interface, the recorded car does not obey']
PALETTE = [('#2a78d6', '#cde2fb'), ('#eb6834', '#fbdccf'), ('#1baf7a', '#c9efe0'), ('#eda100', '#fbe9b8'), ('#6250d6', '#dcd7f7'), ('#e87ba4', '#f9dde8')]
INK, INK2, MUTED, SURF = '#1a1a19', '#4b4a45', '#8a897f', '#ffffff'
BW, BH, GAP, GAP2, X0, Y1, ROWGAP = 150, 80, 92, 170, 36, 110, 230
FONT = "ui-sans-serif, system-ui, 'Segoe UI', Helvetica, Arial, sans-serif"; MONO = "ui-monospace, 'DejaVu Sans Mono', Menlo, monospace"
EV_SHORT = {'measured:rhc_store': 'rhc_store', 'exact:message_address': 'msg address', 'exact:message_filters': 'msg_filters', 'measured:sample_identity': 'sample id',
            'exact:sample_identity': 'sample id', 'measured:request-id': 'request id', 'container:observed': 'container op', 'pointer:held@publish': 'held@publish', 'probe:band': 'method probe', 'probe:latest': 'method probe'}


def ms(v):
    return '' if v is None else (f"{v / 1e6:.2f} ms" if v < 1e7 else f"{v / 1e6:.1f} ms")


def main():
    ap = argparse.ArgumentParser(); ap.add_argument('json'); ap.add_argument('-o', '--out', required=True); ap.add_argument('--html'); ap.add_argument('--spec')
    ap.add_argument('--title', default='Autoware logging_simulator replay with a route — the end-to-end chain as FISH extracts it: sensing → perception → planning → control')
    ap.add_argument('--highlight', default='', help='comma-separated evidence labels (prov) drawn red, e.g. probe:band,container:observed,pointer:held@publish')
    ap.add_argument('--highlight-note', default='evidence mechanism added this week', help='legend text for the red links')
    ap.add_argument('--highlight-topics', default='', help='comma-separated topic substrings drawn orange (e.g. /planning/,/control/)')
    ap.add_argument('--highlight-topics-note', default='observable only since this week', help='legend text for the orange links')
    a = ap.parse_args()
    HL = {x for x in a.highlight.split(',') if x}; HLT = [x for x in a.highlight_topics.split(',') if x]
    RED, ORANGE = '#d93a36', '#e08a00'

    def link_colour(L):
        if L['prov'] in HL or L['kind'] in HL: return RED
        if HLT and any(x in (L.get('topic') or '') for x in HLT): return ORANGE
        return INK2
    d = json.load(open(a.json)); T = {t['id']: t for t in d['tasks']}
    VT = {v['id']: t['id'] for t in d['tasks'] for v in t['vertices']}
    E = {(e['u'], e['v']): e for t in d['tasks'] for e in t['edges']}
    chain, row_breaks, side, spec_v = DEFAULT_CHAIN, DEFAULT_ROW_BREAKS, DEFAULT_SIDE, None
    if a.spec:
        sp = json.load(open(a.spec)); row_breaks = sp.get('row_breaks', row_breaks); side = {int(k): tuple(v) for k, v in sp.get('side', {}).items()}
        if 'vertices' in sp: spec_v = sp                                   # chain_find.py output: the path itself
        else: chain = [tuple(x) + (None,) * (4 - len(x)) for x in sp['chain']]

    def find(node, ent):
        c = [(t['id'], v) for t in d['tasks'] for v in t['vertices'] if node in (v.get('node') or v.get('name') or '') and ent in str(v.get('entity') or v.get('name') or '')]
        if not c:
            s = [(t['id'], x) for t in d['tasks'] for x in t['sources'] if node in x['name'] and ent in x['name']]
            if len(s) == 1:
                tid, x = s[0]; return tid, dict(id=x['vertex'], name=x['name'], node=node, entity=ent, C=None, n=x.get('n_releases'), source=True, ia=(x.get('inter_arrival') or {}).get('p50'))
        if len(c) > 1:   # several callbacks match (e.g. a node with many timers of the same period): the one in the largest task, then the busiest
            c.sort(key=lambda x: (-T[x[0]]['size'], -(((x[1].get('C') or {}).get('p50')) or 0)))
            print(f"note: {node} {ent}: {len(c)} matches, using task {c[0][0]} {c[0][1]['name'][-50:]}")
        assert c, f"{node} {ent}: no match"
        return c[0]
    if spec_v:
        VALL = {v['id']: (t['id'], v) for t in d['tasks'] for v in t['vertices']}
        for t in d['tasks']:
            for x in t['sources']:
                if x.get('kind') == 'stimulus' and x['vertex'] not in VALL:
                    VALL[x['vertex']] = (t['id'], dict(id=x['vertex'], name=x['name'], node=x['name'].split(' / ')[0], entity=x['name'].split('→')[-1].strip(), C=None, n=x.get('n_releases'), source=True, ia=(x.get('inter_arrival') or {}).get('p50')))
        boxes = [(*VALL[i], lab, None) for i, lab in zip(spec_v['vertices'], spec_v['labels'])]
        links = [dict(kind=L['kind'], prov=L['prov'], hop=L['hop'], n=L['n'], style=L['style'], topic=L.get('topic')) for L in spec_v['links']]
        if not side: side = {}
    else:
        boxes = [(*find(node, ent), label, hint) for node, ent, label, hint in chain]        # (task, vertex, label, hint)
        links = []
    for (ta, va, _, _), (tb, vb, _, hint) in ([] if spec_v else zip(boxes, boxes[1:])):
        e = E.get((va['id'], vb['id']))
        if e is not None:
            links.append(dict(kind=e['kind'], prov=e.get('prov') or '', hop=(e.get('delta') or {}).get('p50'), n=e.get('n_pairs'), style='solid')); continue
        s = [x for x in d['sampled'] if x['reader_vertex'] == vb['id'] and (x['writer_vertex'] == va['id'] or ta in (x.get('writer_tasks') or []))]
        if hint: s = [x for x in s if hint in (x['topic'] or '')] or s
        if s:
            x = s[0]; links.append(dict(kind='sampled', prov=f"{x.get('method')}", hop=x.get('age_p50'), n=x.get('n'), style='dotted', topic=x['topic'])); continue
        c = [x for x in d['candidates'] if x['u'] == va['id'] and x['v'] == vb['id']]
        if c:
            links.append(dict(kind=c[0].get('nature', 'candidate'), prov='no evidence record', hop=None, n=None, style='dotted', topic=c[0].get('topic'))); continue
        links.append(dict(kind='?', prov='no link found', hop=None, n=None, style='dotted'))
    # tasks in order of appearance -> colours
    tasks_used = []
    for t_, *_ in boxes:
        if t_ not in tasks_used: tasks_used.append(t_)
    col = {t_: PALETTE[i % len(PALETTE)] for i, t_ in enumerate(tasks_used)}
    # geometry: rows
    row_of = []; r = 0
    for i in range(len(boxes)):
        while r < len(row_breaks) and i >= row_breaks[r]: r += 1
        row_of.append(r)
    pos = []; x = X0
    for i in range(len(boxes)):
        if i > 0 and row_of[i] != row_of[i - 1]: x = X0
        pos.append((x, Y1 + row_of[i] * ROWGAP))
        if i < len(links): x += BW + (GAP2 if links[i]['style'] != 'solid' else GAP)
    nrows = row_of[-1] + 1
    W = max(px for px, _ in pos) + BW + X0 + 40; H = Y1 + (nrows - 1) * ROWGAP + BH + 150 + (24 if HL else 0) + (20 if HLT else 0)
    out = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}" font-family="{FONT}">',
           f'<rect width="{W}" height="{H}" fill="{SURF}"/>',
           ('<defs>' + ''.join('<marker id="%s" viewBox="0 0 8 8" refX="7.5" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0.5 L7.5,4 L0,7.5 z" fill="%s"/></marker>' % (mid, mc) for mid, mc in (('ah', INK2), ('ahr', RED), ('aho', ORANGE))) + '</defs>'),
           f'<text x="{X0}" y="34" font-size="19" font-weight="600" fill="{INK}">{html.escape(a.title)}</text>',
           f'<text x="{X0}" y="56" font-size="12.5" fill="{INK2}">session {html.escape(d["session"])} · box: callback (node / entity), C = execution time p50, n = instances in the steady window · solid arrow: trigger edge inside a task, label = evidence · hop latency p50 · dotted arrow: link between tasks (sampled read with its measured age, or a state candidate)</text>']
    last_in_row = {row_of[i]: i for i in range(len(boxes))}
    for i, (task, v, label, _) in enumerate(boxes):
        x, y = pos[i]; c, tint = col[task]
        if i in side:
            txt, above = side[i]; last = (i == last_in_row[row_of[i]]); first = (i == 0 or row_of[i - 1] != row_of[i])
            tx, anc = (x + BW, 'end') if last else ((x, 'start') if first else (x + BW / 2, 'middle'))
            ty = (y - 44) if above else (y + BH + 34)
            out.append(f'<text x="{tx}" y="{ty}" text-anchor="{anc}" font-size="10.5" fill="{MUTED}">{html.escape(txt)}</text>')
            ay0, ay1 = ((y - 36), y - 2) if above else ((y + BH + 30), y + BH + 2)
            out.append(f'<line x1="{x + BW / 2}" y1="{ay0}" x2="{x + BW / 2}" y2="{ay1}" stroke="{MUTED}" stroke-width="1.5" stroke-dasharray="3 3" marker-end="url(#ah)"/>')
        out.append(f'<rect x="{x}" y="{y}" width="{BW}" height="{BH}" rx="6" fill="{tint}" stroke="{c}" stroke-width="1.6"/>')
        lines = label.split('\n'); y0 = y + 20 if len(lines) >= 3 else y + 27
        for j, line in enumerate(lines):
            out.append(f'<text x="{x + BW / 2}" y="{y0 + j * 15}" text-anchor="middle" font-size="12" font-weight="{600 if j == 0 or (len(lines) >= 3 and j == 1) else 400}" fill="{INK}">{html.escape(line)}</text>')
        C = (v.get('C') or {}).get('p50'); n = v.get('n')
        meta = (f"n {n} · T {ms(v.get('ia'))}" if v.get('source') else ' · '.join(s for s in [f"C {ms(C)}" if C is not None else '', f"n {n}" if n else ''] if s))
        out.append(f'<text x="{x + BW / 2}" y="{y + BH - 8}" text-anchor="middle" font-size="10.5" font-family="{MONO}" fill="{INK2}">{html.escape(meta)}</text>')
    for i, L in enumerate(links):
        (xa, ya), (xb, yb) = pos[i], pos[i + 1]; dash = '' if L['style'] == 'solid' else ' stroke-dasharray="2.5 4"'
        if str(L['kind']).startswith('probe') or 'probe' in str(L.get('prov')) and L['style'] != 'solid':
            lab1, lab2 = f"state read · age {ms(L['hop'])}", f"method probe: {(L.get('topic') or '')[-44:]}"      # node-internal state, deposit → latest read, observed by the typed method probes
        elif L['kind'] in ('sampled', 'polled_take') or (L['style'] != 'solid' and 'candidate' not in L['kind']): lab1, lab2 = f"polled read · age {ms(L['hop'])}", (L.get('topic') or 'sampled dependency')[-30:]
        elif L['style'] != 'solid': lab1, lab2 = L['kind'].replace('_', ' '), 'no evidence record'
        else: lab1, lab2 = f"{L['kind']} · {ms(L['hop'])}", EV_SHORT.get(L['prov'], L['prov'][:16])
        lc = link_colour(L); lw = '2.6' if lc != INK2 else '1.8'; mk = {RED: 'ahr', ORANGE: 'aho'}.get(lc, 'ah'); tc = lc if lc != INK2 else INK; tc2 = lc if lc != INK2 else MUTED
        if row_of[i + 1] == row_of[i]:
            x1, x2, yy = xa + BW, xb, ya + BH / 2; cx = (x1 + x2) / 2
            out.append(f'<line x1="{x1 + 1}" y1="{yy}" x2="{x2 - 1}" y2="{yy}" stroke="{lc}" stroke-width="{lw}"{dash} marker-end="url(#{mk})"/>')
            out.append(f'<text x="{cx}" y="{yy - 10}" text-anchor="middle" font-size="10.5" font-weight="600" fill="{tc}">{html.escape(lab1)}</text>')
            out.append(f'<text x="{cx}" y="{yy + 18}" text-anchor="middle" font-size="9.5" font-family="{MONO}" fill="{tc2}">{html.escape(lab2)}</text>')
        else:
            x1, y1 = xa + BW / 2, ya + BH; x2, y2 = xb + BW / 2, yb; ym = (y1 + y2) / 2
            out.append(f'<path d="M{x1},{y1 + 1} V{ym} H{x2} V{y2 - 1}" fill="none" stroke="{lc}" stroke-width="{lw}"{dash} marker-end="url(#{mk})"/>')
            out.append(f'<text x="{(x1 + x2) / 2}" y="{ym - 8}" text-anchor="middle" font-size="10.5" font-weight="600" fill="{tc}">{html.escape(lab1)}</text>')
            out.append(f'<text x="{(x1 + x2) / 2}" y="{ym + 14}" text-anchor="middle" font-size="9.5" font-family="{MONO}" fill="{tc2}">{html.escape(lab2)}</text>')
    xl, yl = pos[-1]
    for j, line in enumerate(END_NOTE):
        out.append(f'<text x="{xl + BW}" y="{yl + BH + 18 + 13 * j}" text-anchor="end" font-size="10.5" fill="{INK2}">{html.escape(line)}</text>')
    # per-task segment totals (solid hops + callback C along the chain)
    seg = []
    for t_ in tasks_used:
        idx = [i for i, b in enumerate(boxes) if b[0] == t_]
        hops = [links[i] for i in idx if i < len(links) and links[i]['style'] == 'solid' and boxes[i + 1][0] == t_]
        Cs = sum(((boxes[i][1].get('C') or {}).get('p50') or 0) for i in idx)
        src = T[t_]['sources'][0]['name'] if T[t_]['sources'] else ''
        seg.append((t_, len(hops), sum(L['hop'] or 0 for L in hops), Cs, src))
    ly = Y1 + (nrows - 1) * ROWGAP + BH + 58
    out.append(f'<text x="{X0}" y="{ly}" font-size="12" fill="{INK}">along the chain, per task: ' + ' · '.join(f"task {t_}: {nh} hops, Σ hop p50 {hop / 1e6:.1f} ms, Σ C p50 {Cs / 1e6:.1f} ms" for t_, nh, hop, Cs, _ in seg)
               + ' · between tasks: the dotted links (age = how old the read sample was)</text>')
    lx = X0
    for t_, nh, hop, Cs, src in seg:
        c, tint = col[t_]; name = f"task {t_} — source: {src.split(' / ')[-1][:34]} ({src.split(' / ')[0].split('/')[-1][:28]})"
        out.append(f'<rect x="{lx}" y="{ly + 16}" width="14" height="14" rx="3" fill="{tint}" stroke="{c}" stroke-width="1.5"/>')
        out.append(f'<text x="{lx + 20}" y="{ly + 28}" font-size="11.5" fill="{INK2}">{html.escape(name)}</text>'); lx += 20 + 6.9 * len(name) + 26
    out.append(f'<line x1="{X0}" y1="{ly + 52}" x2="{X0 + 36}" y2="{ly + 52}" stroke="{INK2}" stroke-width="1.8" marker-end="url(#ah)"/><text x="{X0 + 44}" y="{ly + 56}" font-size="11.5" fill="{INK2}">trigger edge (observed, identity-paired: DDS reader-cache record, intra-process address, message_filters, method probe)</text>')
    out.append(f'<line x1="{X0 + 640}" y1="{ly + 52}" x2="{X0 + 676}" y2="{ly + 52}" stroke="{INK2}" stroke-width="1.8" stroke-dasharray="2.5 4" marker-end="url(#ah)"/><text x="{X0 + 684}" y="{ly + 56}" font-size="11.5" fill="{INK2}">link between tasks: sampled read (measured age) or state candidate (no evidence record)</text>')
    if HL or HLT:
        yh = ly + 76; xh = X0
        if HL:
            nred = sum(1 for L in links if link_colour(L) == RED)
            out.append(f'<line x1="{xh}" y1="{yh}" x2="{xh + 36}" y2="{yh}" stroke="{RED}" stroke-width="2.6" marker-end="url(#ahr)"/><text x="{xh + 44}" y="{yh + 4}" font-size="11.5" fill="{RED}">{html.escape(a.highlight_note)} ({nred} link(s): {html.escape(", ".join(sorted(HL)))})</text>')
            xh += 44 + 6.9 * (len(a.highlight_note) + len(', '.join(sorted(HL))) + 14) + 30
        if HLT:
            nor = sum(1 for L in links if link_colour(L) == ORANGE); yh2 = yh + 20 if HL else yh
            out.append(f'<line x1="{X0}" y1="{yh2}" x2="{X0 + 36}" y2="{yh2}" stroke="{ORANGE}" stroke-width="2.6" marker-end="url(#aho)"/><text x="{X0 + 44}" y="{yh2 + 4}" font-size="11.5" fill="{ORANGE}">{html.escape(a.highlight_topics_note)} ({nor} link(s))</text>')
    out.append('</svg>')
    svg = '\n'.join(out); open(a.out, 'w').write(svg)
    if a.html:
        open(a.html, 'w').write(f'<!doctype html><html><head><meta charset="utf-8"><title>FISH chain</title><style>body{{margin:0;background:#f4f4f2}} .w{{padding:16px;overflow:auto}}</style></head><body><div class="w">{svg}</div></body></html>')
    print(f"{a.out}: {len(boxes)} boxes, {len(links)} links ({sum(1 for L in links if L['style'] == 'solid')} trigger edges), {nrows} rows, {W}x{H}")
    for b, L in zip(boxes, links + [None]):
        print(f"  T{b[0]:<3} {b[1]['name'][-66:]:<66} C={ms((b[1].get('C') or {}).get('p50')):>9} n={b[1].get('n')}" + (f"  ⇒ {L['kind']} {L['prov'][:22]} {ms(L['hop'])} n={L.get('n')}" if L else ''))


if __name__ == '__main__':
    main()
